def monotonic(l: list) -> bool:
    if not l or len(l) <= 2:
        return True

    is_increasing = True
    is_decreasing = True

    for i in range(len(l) - 1):
        if l[i] < l[i+1]:
            is_decreasing = False
        if l[i] > l[i+1]:
            is_increasing = False

    return is_increasing or is_decreasing
